import numpy as np
from rdkit import Chem
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
mols=[Chem.AddHs(Chem.MolFromSmiles('Cc1ccc2ccc(CP(C(C)(C)C)C(C)(C)C)nc2n1')),Chem.AddHs(Chem.MolFromSmiles('CC(C)c1ccc(C)cc1')),Chem.AddHs(Chem.MolFromSmiles('CC#N'))]
d=np.load('final_coords.npz');x=d['coords'];els=d['elements']
bonds=[];o=0
for m in mols:
 for b in m.GetBonds():bonds.append((o+b.GetBeginAtomIdx(),o+b.GetEndAtomIdx(),False))
 o+=m.GetNumAtoms()
bonds.extend([(78,18,True),(78,9,True),(78,74,True)])
for r in [3,4,5,6,8,9]:bonds.append((78,48+r,True))
colors={'C':'#424242','N':'#2460d9','P':'#f39600','Ru':'#cb43a1','H':'#c2c2c2'}
fig=plt.figure(figsize=(12,6))
for panel,(elv,azim) in enumerate([(15,-75),(60,-120)]):
 ax=fig.add_subplot(1,2,panel+1,projection='3d')
 for i,j,dash in bonds:
  ax.plot(*x[[i,j]].T,color='gray' if dash else '#666666',linestyle=':' if dash else '-',linewidth=.9)
 for i,el in enumerate(els):
  ax.scatter(*x[i],color=colors[el],s=20 if el=='H' else 90 if el=='Ru' else 50,edgecolors='black',linewidths=.3)
  if el in ['Ru','N','P']:ax.text(*x[i],f'{el}{i}',fontsize=9)
 ax.set_box_aspect((1,1,1));ax.view_init(elv,azim)
 ax.set_axis_off()
fig.tight_layout();fig.savefig('structure.png',dpi=160)
# minimum nonbonded interligand distances
for a,b in [(range(48),range(48,72)),(range(48),range(72,78)),(range(48,72),range(72,78))]:
 out=[]
 for i in a:
  for j in b:out.append((np.linalg.norm(x[i]-x[j]),i,j,els[i],els[j]))
 print(sorted(out)[:5])
